@@ -7,6 +7,7 @@ import 'package:http/http.dart' as http;
 import 'package:path_provider/path_provider.dart';

 import 'package:fa/services/app_log.dart';
+import 'package:fa/services/dap_home.dart';
 import 'package:fa/services/project_folder_channel.dart';
 import 'package:fa/services/project_mount_env.dart';
 import 'package:fa/services/project_mount_store.dart';
@@ -70,6 +71,9 @@ Future<ExecutionEnv> createMobileSandboxEnv({
   final appDir = await getApplicationDocumentsDirectory();
   final sandbox = Directory('${appDir.path}/fah_sandbox');
   await sandbox.create(recursive: true);
+  // Android/iOS have no HOME and a read-only `/`: keep the `~/.dap` hub
+  // config inside the sandbox so Settings → Agent network survives restarts.
+  dapHomeOverride = sandbox.path;

   // Both Android and iOS run the WASI sandbox shell; on iOS the wasm_run
   // library is statically linked into the app binary (see setUpWasmRuntime).
diff --git a/flutter_app/lib/services/dap_home.dart b/flutter_app/lib/services/dap_home.dart
new file mode 100644
index 000000000..167a2cf5e
--- /dev/null
+++ b/flutter_app/lib/services/dap_home.dart
@@ -0,0 +1,16 @@
+// Copyright (c) 2026, the Flutter Agent Harness authors.
+// Use of this source code is governed by a MIT license that can be found
+// in the LICENSE file.
+
+/// Writable "home" for the `~/.dap` layout on sandboxed mobile hosts.
+///
+/// Android/iOS app processes have no `HOME` and a read-only `/` cwd, so the
+/// hub client's default (`${HOME ?? cwd}/.dap/config.json`) resolves to
+/// `/.dap/config.json` and every save silently fails. The mobile sandbox
+/// factory sets this to the app's `fah_sandbox` directory; desktop leaves it
+/// null (real `~`).
+String? dapHomeOverride;
+
+/// Resolves the home [IoDapHubService] should use: an explicit [home] wins,
+/// then [dapHomeOverride], else null (the package default).
+String? resolveDapHome(String? home) => home ?? dapHomeOverride;
diff --git a/flutter_app/lib/services/dap_service_io.dart b/flutter_app/lib/services/dap_service_io.dart
index db9e3e6e2..d273eac4c 100644
--- a/flutter_app/lib/services/dap_service_io.dart
+++ b/flutter_app/lib/services/dap_service_io.dart
@@ -12,6 +12,7 @@ import 'package:flutter_agent_harness/flutter_agent_harness.dart'
     show JsonlSessionRepo, SessionMetadata;
 import 'package:flutter_agent_harness/io.dart' show LocalExecutionEnv;

+import 'package:fa/services/dap_home.dart';
 import 'package:fa/services/sessions_root.dart';

 import 'dap_service.dart';
@@ -23,16 +24,21 @@ import 'dap_service.dart';
 final class IoDapHubService implements DapHubService {
   IoDapHubService({
     Map<String, String>? environment,
-    this.home,
+    String? home,
     this.probeTimeout = const Duration(seconds: 5),
-  }) : environment = environment ?? Platform.environment;
+  }) : environment = environment ?? Platform.environment,
+       _home = home;

   /// Injected environment (defaults to `Platform.environment`; test seam —
   /// pointing `HOME` at a temp dir keeps tests off the real `~/.dap`).
   final Map<String, String> environment;

-  /// Home directory for the `~/.dap` layout (test seam).
-  final String? home;
+  final String? _home;
+
+  /// Home directory for the `~/.dap` layout: the injected test seam, else the
+  /// mobile sandbox ([dapHomeOverride] — `/` is read-only on Android/iOS),
+  /// else null (the package's `$HOME`).
+  String? get home => resolveDapHome(_home);

   /// How long the live probe waits for the hub's welcome before reporting
   /// unreachable — the client keeps reconnecting forever otherwise.
diff --git a/flutter_app/test/services/dap_home_test.dart b/flutter_app/test/services/dap_home_test.dart
new file mode 100644
index 000000000..008517a9e
--- /dev/null
+++ b/flutter_app/test/services/dap_home_test.dart
@@ -0,0 +1,31 @@
+import 'dart:io';
+
+import 'package:fa/services/dap_home.dart';
+import 'package:fa/services/dap_service_io.dart';
+import 'package:flutter_test/flutter_test.dart';
+
+void main() {
+  tearDown(() => dapHomeOverride = null);
+
+  test(
+    'mobile sandbox home persists the hub URL when HOME is unusable',
+    () async {
+      final dir = await Directory.systemTemp.createTemp('dap_home');
+      addTearDown(() => dir.delete(recursive: true));
+      dapHomeOverride = dir.path;
+      // Android shape: no HOME / USERPROFILE in the environment.
+      final svc = IoDapHubService(environment: const {});
+      await svc.saveConnection(url: 'ws://127.0.0.1:8787/ws', name: 'phone');
+      expect(File('${dir.path}/.dap/config.json').existsSync(), isTrue);
+      // A fresh service (= app restart) reads the saved URL back.
+      final again = IoDapHubService(environment: const {});
+      expect((await again.load()).url, 'ws://127.0.0.1:8787/ws');
+    },
+  );
+
+  test('explicit home beats the override', () {
+    dapHomeOverride = '/a';
+    expect(resolveDapHome('/b'), '/b');
+    expect(resolveDapHome(null), '/a');
+  });
+}

