// Copyright (c) 2026, the Flutter Agent Harness authors.
// Use of this source code is governed by a MIT license that can be found
// in the LICENSE file.

import 'dart:async';
import 'dart:convert';
import 'dart:io';

import 'package:fa_hub_client/fa_hub_client.dart';
import 'package:flutter/foundation.dart' show visibleForTesting;
import 'package:flutter_agent_harness/flutter_agent_harness.dart'
    show JsonlSessionRepo, SessionMetadata;
import 'package:flutter_agent_harness/io.dart' show LocalExecutionEnv;

import 'package:fa/services/sessions_root.dart';

import 'dap_service.dart';

/// The real [DapHubService] (IO platforms): reads/writes the same
/// machine-shared `~/.dap` config the CLI agents use, via the
/// `fah_hub_client` package's own loader/persister — no second config
/// format.
final class IoDapHubService implements DapHubService {
  IoDapHubService({
    Map<String, String>? environment,
    this.home,
    this.probeTimeout = const Duration(seconds: 5),
  }) : environment = environment ?? Platform.environment;

  /// Injected environment (defaults to `Platform.environment`; test seam —
  /// pointing `HOME` at a temp dir keeps tests off the real `~/.dap`).
  final Map<String, String> environment;

  /// Home directory for the `~/.dap` layout (test seam).
  final String? home;

  /// How long the live probe waits for the hub's welcome before reporting
  /// unreachable — the client keeps reconnecting forever otherwise.
  final Duration probeTimeout;

  /// The effective settings with the documented precedence (docs/dap.md
  /// §9.1): env (`DAP_HUB_URL`/`DAP_AGENT_NAME`) > `~/.dap/config.json` >
  /// zero-config defaults — env merged exactly like `HubPlugin.register`.
  DapSettings get _settings {
    final config = HubConfig.fromMap(
      readDapConfig(defaultDapConfigFile(home, environment)),
      environment,
    );
    return resolveDapSettings(
      config: config,
      environment: environment,
      home: home,
    );
  }

  @override
  Future<DapHubSnapshot> load() async {
    final settings = _settings;
    // Created 0600 on first use — the same first-use semantics as the CLI.
    final identity = await HubIdentity.load(settings.keyPath);
    final channels = (await loadChannelKeys(
      settings.channelsFile,
    )).keys.toList()..sort();
    final binding = _readBinding();
    return DapHubSnapshot(
      supported: true,
      url: settings.url,
      name: settings.name,
      agentId: identity.agentId,
      channels: channels,
      envLocked:
          environment.containsKey(HubConfig.envUrl) ||
          environment.containsKey(HubConfig.envName),
      connected: null,
      inboundMode: binding.$1,
      boundSessionId: binding.$2,
      boundSessionTitle: binding.$3,
    );
  }

  /// The `boundSession` block of the raw config (`{mode, sessionId?,
  /// title?}`) — readDapConfig returns the full map, so app-only keys
  /// ride along untouched by the package's persist helpers.
  (DapInboundMode, String?, String?) _readBinding() {
    final raw = readDapConfig(defaultDapConfigFile(home, environment));
    final bound = raw['boundSession'];
    if (bound is! Map) return (DapInboundMode.currentSession, null, null);
    final mode = switch ('${bound['mode'] ?? ''}') {
      'dedicated' => DapInboundMode.dedicated,
      'named' => DapInboundMode.named,
      _ => DapInboundMode.currentSession,
    };
    final title = '${bound['title'] ?? ''}'.trim();
    final id = '${bound['sessionId'] ?? ''}'.trim();
    return (mode, id.isEmpty ? null : id, title.isEmpty ? null : title);
  }

  @override
  Future<void> saveConnection({
    required String url,
    required String name,
    String? secret,
  }) {
    final trimmed = name.trim();
    final password = [REDACTED:Sensitive Value] ?? '').trim();
    return persistDapConfig(
      url: normalizeDapHost(url.trim()),
      name: trimmed.isEmpty ? null : trimmed,
      // The master password dials directly (the hub accepts it as a
      // credential); an empty field keeps whatever is stored.
      clientSecret: [REDACTED:Sensitive Value] ? null : password,
      file: defaultDapConfigFile(home, environment),
    );
  }

  @override
  Future<void> saveBinding(
    DapInboundMode mode, {
    String? sessionId,
    String? sessionTitle,
  }) async {
    final path = defaultDapConfigFile(home, environment);
    final next = Map<String, dynamic>.of(readDapConfig(path));
    if (mode == DapInboundMode.currentSession) {
      next.remove('boundSession');
    } else {
      next['boundSession'] = <String, dynamic>{
        'mode': mode.name,
        if (sessionId != null && sessionId.isNotEmpty) 'sessionId': sessionId,
        if (sessionTitle != null && sessionTitle.isNotEmpty)
          'title': sessionTitle,
      };
    }
    final target = File(path);
    if (!await target.parent.exists()) {
      await target.parent.create(recursive: true);
    }
    await target.writeAsString(
      '${const JsonEncoder.withIndent('  ').convert(next)}\n',
    );
  }

  @override
  Future<List<DapBindableSession>> listBindableSessions() async {
    // The app's own sessions: every candidate root (the shared App Group
    // container + the ~/.fah fallback on macOS), newest activity first.
    final env = LocalExecutionEnv();
    final out = <DapBindableSession>[];
    for (final root in allSessionRoots(
      defaultSessionsRoot(Directory.current.path),
    )) {
      try {
        final repo = JsonlSessionRepo(fs: env, sessionsRoot: root);
        final metas = await repo.list();
        for (final meta in metas) {
          out.add((id: meta.id, title: sessionTitle(meta)));
        }
      } on Object {
        // Unreadable root — other roots still list.
      }
    }
    // Dedup by id (a session visible from two roots lists once).
    final seen = <String>{};
    return [
      for (final entry in out)
        if (seen.add(entry.id)) entry,
    ].take(50).toList();
  }

  /// Display label for the picker: the app-written title/name metadata,
  /// else a short id. Exposed for tests.
  @visibleForTesting
  static String sessionTitle(SessionMetadata meta) =>
      preferredLabel(meta.metadata) ?? shortSessionId(meta.id);

  /// The first non-blank of `title`, `name`, `displayName`, else null.
  static String? preferredLabel(Map<String, dynamic>? raw) {
    for (final key in const ['title', 'name', 'displayName']) {
      final value = raw?[key];
      if (value is String && value.trim().isNotEmpty) return value.trim();
    }
    return null;
  }

  /// `session <first-8-chars>` — the whole id when shorter.
  static String shortSessionId(String id) =>
      'session ${id.length > 8 ? id.substring(0, 8) : id}';

  @override
  Future<DapHubSnapshot> probe() async {
    final snapshot = await load();
    final plugin = HubPlugin(environment: environment, home: home);
    final started = plugin.start();
    var connected = false;
    try {
      await started.timeout(probeTimeout);
      connected = (await plugin.status()).connected;
    } on Object {
      // Timeout (hub not answering) or hub rejection: honest "unreachable".
    } finally {
      await plugin.dispose();
      // fah_hub_client 0.2.5 (verified in hub_plugin.dart): dispose()
      // neither cancels nor awaits an in-flight start() — it only tears
      // down the fields it sees. Two interleavings matter: dispose after
      // start() assigned _repository makes start() die on a null
      // assertion (`_repository!`) — marked handled here, after dispose,
      // so anything dispose induces is covered; dispose before start()
      // touches its fields is a no-op that leaves start() running.
      started.ignore();
      // ponytail: residual ceiling — start() has no cancel API, so a
      // timeout that lands before start() assigns its fields leaves the
      // socket + reconnect loop alive with no owner. Upgrade path: a
      // close()-style API in the package, then await it here.
    }
    return snapshot.withProbe(connected);
  }
}

/// Creates the platform [DapHubService] (IO platforms).
DapHubService createDapHubService() => IoDapHubService();

import 'dart:io';

import 'package:flutter/foundation.dart';
import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:flutter_agent_harness/io.dart';
import 'package:http/http.dart' as http;
import 'package:path_provider/path_provider.dart';

import 'package:fa/services/app_log.dart';
import 'package:fa/services/project_folder_channel.dart';
import 'package:fa/services/project_mount_env.dart';
import 'package:fa/services/project_mount_store.dart';
import 'package:fa/sandbox/fs_persistence_stub.dart'
    if (dart.library.html) 'fs_persistence_web.dart';
import 'package:fa/sandbox/memory_shell.dart';
import 'package:fa/sandbox/persistent_web_env.dart';
import 'package:fa/sandbox/sandbox_host_paths.dart';
import 'package:fa/sandbox/wasm_shell.dart';

/// Creates the execution environment for the current platform.
///
/// Desktop keeps the existing [LocalExecutionEnv] with the host shell. Mobile
/// uses a sandboxed host directory and a WasiSandboxShell backed by
/// MIT-licensed uutils/ripgrep WASM binaries so the agent has a working shell
/// on iOS and Android.
/// The user's home directory on desktop (for user-level skill roots like
/// `~/.claude/skills`, `~/.copilot/skills`); null on mobile/web where those
/// directories do not exist.
///
/// gh-1276 review: the CLI's `homeDirectory()` (`lib/src/cli/cli_config.dart`)
/// falls back to `USERPROFILE` on Windows, where `HOME` is typically unset —
/// the app mirrors that fallback (and `bin/fah.dart`'s `HOME ?? USERPROFILE`
/// order elsewhere) so a Windows desktop build shares the CLI's user store
/// (`%USERPROFILE%/.fah/memory`) instead of silently falling back to a
/// disjoint sandbox-local one. [environment] is injectable for tests.
String? desktopHomeDir([Map<String, String>? environment]) {
  if (kIsWeb || Platform.isAndroid || Platform.isIOS) return null;
  final env = environment ?? Platform.environment;
  if (Platform.isWindows) return env['USERPROFILE'] ?? env['HOME'];
  return env['HOME'] ?? env['USERPROFILE'];
}

Future<ExecutionEnv> createPlatformEnv({http.Client? httpClient}) async {
  if (kIsWeb) {
    // Fallback for the unlikely case this file is compiled for web; the stub
    // implementation is preferred via conditional import.
    return MemoryExecutionEnv(cwd: '/');
  }

  if (Platform.isAndroid || Platform.isIOS) {
    return createMobileSandboxEnv(httpClient: httpClient);
  }
  return createDesktopEnv();
}

/// The Android/iOS branch of [createPlatformEnv]: a sandboxed host directory
/// plus the WASI shell backed by MIT-licensed uutils/ripgrep WASM binaries
/// so the agent has a working shell on mobile.
///
/// Issue #640: if the WASM runtime fails (e.g. a Rust PanicException while
/// JIT-compiling python.wasm inside the Android `untrusted_app` VM limits),
/// the failure used to kill boot before the first frame — a black screen.
/// It now logs a warning and falls back to the pure-Dart [MemoryShell] over
/// a [MemoryExecutionEnv] + [PersistentWebExecutionEnv] (the web shell
/// stack), so the app always boots to the UI.
Future<ExecutionEnv> createMobileSandboxEnv({
  http.Client? httpClient,
  @visibleForTesting Future<WasiSandboxShell> Function()? loadShell,
}) async {
  final appDir = await getApplicationDocumentsDirectory();
  final sandbox = Directory('${appDir.path}/fah_sandbox');
  await sandbox.create(recursive: true);

  // Both Android and iOS run the WASI sandbox shell; on iOS the wasm_run
  // library is statically linked into the app binary (see setUpWasmRuntime).
  try {
    final shell =
        await (loadShell ??
            () => WasiSandboxShell.load(
              workingDirectory: '/',
              sandboxHostPath: sandbox.path,
              httpClient: httpClient,
            ))();
    return SandboxedExecutionEnv(
      LocalExecutionEnv(cwd: sandbox.path, shell: shell),
      sandbox.path,
    );
  } on Object catch (e) {
    final note = 'WASM shell unavailable, falling back to MemoryShell: $e';
    debugPrint('[env_factory] $note');
    AppLog.i('sandbox', note);
    final shell = MemoryShell(httpClient: httpClient);
    final env = MemoryExecutionEnv(cwd: '/', shell: shell);
    shell.attach(env);
    return PersistentWebExecutionEnv.restore(env, createFsSnapshotStore());
  }
}

/// The desktop branch of [createPlatformEnv]: the application-support
/// directory as the container cwd so settings/stores live inside the app
/// sandbox and do not trigger a permission prompt on macOS. macOS
/// additionally layers the optional project-folder mount on top via
/// [mountedDesktopEnv].
Future<ExecutionEnv> createDesktopEnv() async {
  final appDir = await getApplicationSupportDirectory();
  final baseEnv = LocalExecutionEnv(cwd: appDir.path);
  if (!Platform.isMacOS) return baseEnv;
  return mountedDesktopEnv(baseEnv);
}

/// macOS project-folder mount layer over [baseEnv]: restores the persisted
/// mount (bookmark access re-granted → [ProjectMountEnv.mountedRoot], or the
/// stale-mount note when access is refused).
Future<ExecutionEnv> mountedDesktopEnv(LocalExecutionEnv baseEnv) async {
  final mountEnv = ProjectMountEnv(baseEnv);
  final stored = await ProjectMountStore.load(baseEnv);
  if (stored == null) return mountEnv;
  applyStoredMount(
    mountEnv,
    stored,
    granted: await ProjectFolderChannelOps().startAccessing(stored.bookmark),
  );
  return mountEnv;
}

/// Applies a restored mount to [mountEnv]: a granted bookmark exposes the
/// project folder as the mounted root; a refused one surfaces the
/// stale-mount note (public so both branches are table-tested).
void applyStoredMount(
  ProjectMountEnv mountEnv,
  ProjectMountStore stored, {
  required bool granted,
}) {
  if (granted) {
    mountEnv.mountedRoot = stored.path;
  } else {
    mountEnv.mountUnavailable = stored.path;
  }
}

/// `true` when running on a mobile OS that needs the WASM shell sandbox.
bool get isMobile => Platform.isAndroid || Platform.isIOS;

/// `true` when running on Android (the WASM shell sandbox works there).
bool get isAndroidPlatform => Platform.isAndroid;

/// `true` when running on iOS (the WASM shell sandbox works there via the
/// statically linked wasm_run library).
bool get isIosPlatform => Platform.isIOS;

/// `true` when running on the web.
bool get isWebPlatform => false;

/// Maps sandbox-absolute paths (`/foo`) into the sandbox host directory for
/// the file tools, so `read`/`write`/`ls`/`edit` agree with the WASM shell's
/// view of `/` as the sandbox root.
///
/// The mapping is idempotent: paths already inside the sandbox host directory
/// pass through unchanged. That matters because this env reports the *host*
/// path as [cwd], so any path derived from values the env itself hands out —
/// `'${env.cwd}/sessions'`, [absolutePath]/[joinPath] results, or
/// [FileInfo.path] from [listDir] — must remain valid input. Without the
/// pass-through, `JsonlSessionRepo(fs: env, sessionsRoot: '${env.cwd}/
/// sessions')` resolved and wrote sessions into a nested
/// `<sandbox>/<sandbox-host-path>/sessions` directory.
///
/// A sandbox-virtual absolute path that textually begins with the host root
/// is indistinguishable from an already-mapped host path and is treated as
/// the latter; both readings stay inside the sandbox, so the sandbox
/// boundary is preserved either way.
final class SandboxedExecutionEnv
    implements
        ExecutionEnv,
        BackgroundShell,
        RangedReadFileSystem,
        RenamableFileSystem {
  /// Creates an env mapping sandbox-absolute paths onto [_sandboxRoot],
  /// delegating everything else (relative paths, [exec]) to [_delegate].
  SandboxedExecutionEnv(this._delegate, this._sandboxRoot);

  final ExecutionEnv _delegate;
  final String _sandboxRoot;

  /// Lazily-built matcher sharing the "inside the sandbox host dir"
  /// convention with the WASM shell (gh-1274 review) so the two mappings
  /// cannot drift apart.
  SandboxHostRoot? _hostRoot;

  String _map(String path) {
    final root = _sandboxRoot;
    if (root.isEmpty) return path;
    final hostRoot = _hostRoot ??= SandboxHostRoot(root);
    if (hostRoot.contains(path)) return path;
    if (path.startsWith('/')) return '$root$path';
    return path;
  }

  @override
  String get cwd => _delegate.cwd;

  @override
  Future<Result<ShellExecResult, ExecutionError>> exec(
    String command, {
    ShellExecOptions? options,
  }) => _delegate.exec(command, options: options);

  // Background shell jobs: the registry's log path is derived from [cwd]
  // (already a host path), so it needs no mapping — just forward.

  @override
  bool get backgroundJobsSupported {
    final delegate = _delegate;
    if (delegate case final BackgroundShell bg) {
      return bg.backgroundJobsSupported;
    }
    return false;
  }

  @override
  Future<Result<ShellJob, ExecutionError>> startShellJob(
    String command, {
    required String id,
    required String logPath,
    ShellExecOptions? options,
  }) {
    final delegate = _delegate;
    if (delegate case final BackgroundShell bg) {
      return bg.startShellJob(
        command,
        id: id,
        logPath: logPath,
        options: options,
      );
    }
    return Future.value(
      const Err(
        ExecutionError(
          ExecutionErrorCode.shellUnavailable,
          'background shell jobs are not supported by this shell',
        ),
      ),
    );
  }

  @override
  Future<Result<String, FileError>> absolutePath(String path) =>
      _delegate.absolutePath(_map(path));

  @override
  Future<Result<String, FileError>> joinPath(List<String> parts) =>
      _delegate.joinPath(parts);

  @override
  Future<Result<String, FileError>> readTextFile(String path) =>
      _delegate.readTextFile(_map(path));

  @override
  Future<Result<Uint8List, FileError>> readBinaryFile(String path) =>
      _delegate.readBinaryFile(_map(path));

  @override
  Future<Result<Uint8List, FileError>> readRange(
    String path,
    int start,
    int end,
  ) {
    final delegate = _delegate;
    if (delegate case final RangedReadFileSystem ranged) {
      return ranged.readRange(_map(path), start, end);
    }
    return Future.value(
      Err(
        FileError(
          FileErrorCode.notSupported,
          'readRange not supported by $delegate',
          path: path,
        ),
      ),
    );
  }

  @override
  Future<Result<void, FileError>> renamePath(String from, String to) {
    final delegate = _delegate;
    if (delegate case final RenamableFileSystem renamable) {
      return renamable.renamePath(_map(from), _map(to));
    }
    return Future.value(
      Err(
        FileError(
          FileErrorCode.notSupported,
          'renamePath not supported by $delegate',
          path: from,
        ),
      ),
    );
  }

  @override
  Future<Result<List<String>, FileError>> readTextLines(
    String path, {
    int? maxLines,
  }) => _delegate.readTextLines(_map(path), maxLines: maxLines);

  @override
  Future<Result<void, FileError>> writeBinaryFile(
    String path,
    Uint8List content,
  ) => _delegate.writeBinaryFile(_map(path), content);

  @override
  Future<Result<void, FileError>> writeFile(String path, String content) =>
      _delegate.writeFile(_map(path), content);

  @override
  Future<Result<void, FileError>> appendFile(String path, String content) =>
      _delegate.appendFile(_map(path), content);

  @override
  Future<Result<FileInfo, FileError>> fileInfo(String path) =>
      _delegate.fileInfo(_map(path));

  @override
  Future<Result<List<FileInfo>, FileError>> listDir(String path) =>
      _delegate.listDir(_map(path));

  @override
  Future<Result<bool, FileError>> exists(String path) =>
      _delegate.exists(_map(path));

  @override
  Future<Result<void, FileError>> createDir(
    String path, {
    bool recursive = true,
  }) => _delegate.createDir(_map(path), recursive: recursive);

  @override
  Future<Result<void, FileError>> remove(
    String path, {
    bool recursive = false,
    bool force = false,
  }) => _delegate.remove(_map(path), recursive: recursive, force: force);
