  /// cannot drift apart.
  SandboxHostRoot? _hostRoot;

  String _map(String path) {
    final root = _sandboxRoot;
    if (root.isEmpty) return path;
    final hostRoot = _hostRoot ??= SandboxHostRoot(root);
    if (hostRoot.contains(path)) return path;
