        ExecutionEnv,
        BackgroundShell,
        RangedReadFileSystem,
        RenamableFileSystem {
  /// Creates an env mapping sandbox-absolute paths onto [_sandboxRoot],
  /// delegating everything else (relative paths, [exec]) to [_delegate].
