}) {
  final root = _withTrailingSlash(home ?? defaultHome(environment));
  final file = readDapConfig(defaultDapConfigFile(root, environment));
  String? optStr(String key) =>
      file[key] is String && (file[key] as String).isNotEmpty
          ? file[key] as String
