  final baseEnv = LocalExecutionEnv(
    cwd: Directory.systemTemp.createTempSync('fah_base_').path,
  );
  addTearDown(() => Directory(baseEnv.cwd).deleteSync(recursive: true));
  await ProjectMountStore.save(
    baseEnv,
    path: '/proj',
    bookmark: 'bm',
    scoped: true,
  );

